tests='TUVW'; modes='ABCD'; costs=list(map(F,['0.8','1.2','0.7','1.4']))
loss=[[0,24,11,6],[19,0,19,8],[9,10,0,16],[21,24,20,0]]
def weight(s): return sum(rows[i][1] for i in s)
def stop(s):
 return min((F(sum(rows[i][1]*loss[a][modes.index(rows[i][0])] for i in s),weight(s)),modes[a]) for a in range(4))
def branch(s,t,v): return tuple(i for i in s if rows[i][2][t]==v)
def solve(s,available,budget):
 options=[stop(s)]
 if budget:
  for t in available:
   value=costs[t]
   for v in [0,1]:
    b=branch(s,t,v)
    if b: value+=F(weight(b),weight(s))*solve(b,tuple(x for x in available if x!=t),budget-1)[0]
   options.append((value,tests[t]))
 return min(options)
s=tuple(range(8)); first_losses={'STOP':float(stop(s)[0])}
for t in range(4):
 val=costs[t]
 for v in [0,1]:
  b=branch(s,t,v)
  if b: val+=F(weight(b),weight(s))*solve(b,tuple(x for x in range(4) if x!=t),1)[0]
 first_losses[tests[t]]=float(val)
value,action=solve(s,tuple(range(4)),2)
next_actions={}
if action in tests:
 t=tests.index(action)
 for v in [0,1]:
  b=branch(s,t,v)
  next_actions[str(v)]=solve(b,tuple(x for x in range(4) if x!=t),1)[1] if b else 'IMPOSSIBLE'
print({'first':action,'first_losses':first_losses,'next':next_actions})
# Independent fixed-policy check: enumerate each possible second action per first-result.
for t in range(4):
 total=costs[t]
 for v in [0,1]:
  b=branch(s,t,v)
  if not b: continue
  candidates=[stop(b)[0]*weight(b)]
  for u in range(4):
   if u==t: continue
   raw=costs[u]*weight(b)
   for w in [0,1]:
    c=branch(b,u,w)
    if c: raw+=min(sum(rows[i][1]*loss[a][modes.index(rows[i][0])] for i in c) for a in range(4))
   candidates.append(raw)
  total+=min(candidates)/weight(s)
 assert abs(float(total)-first_losses[tests[t]])<1e-12
print('Independent weighted-loss enumeration agrees for all four first tests.')

