from fractions import Fraction as F
modes='ABCD'
rows=[('A',15,1,0,1),('B',6,1,0,0),('B',5,0,1,0),('D',14,0,0,0)] # conditioned on V=0; repeated stored reading adds no evidence
loss={'A':[0,24,11,6],'B':[19,0,19,8],'C':[9,10,0,16],'D':[21,24,20,0]}
prices={'T':F('0.8'),'U':F('1.2'),'W':F('7.4')}
cols={'T':2,'U':3,'W':4}
def best(rs):
 return min((sum(F(r[1])*loss[a][modes.index(r[0])] for r in rs),a) for a in modes)
def entry():
 total=sum(r[1] for r in rows)
 posterior={m:float(F(sum(r[1] for r in rows if r[0]==m),total)) for m in modes}
 remaining={a:float(F(sum(r[1]*loss[a][modes.index(r[0])] for r in rows),total)) for a in modes}
 policies={}
 for t,col in cols.items():
  value=prices[t]; policies[t]={}
  for v in [0,1]:
   b=[r for r in rows if r[col]==v]
   if b:
    raw,a=best(b); value+=raw/total; policies[t][str(v)]=a
   else: policies[t][str(v)]='IMPOSSIBLE'
  remaining[t]=float(value)
 action=min(remaining,key=remaining.get)
 return {'posterior':posterior,'remaining_losses':remaining,'action':action,'repair_after':policies.get(action,{})}
result=entry()
# Independent hand-derived totals: A repair 348/40; T cost .8 + (126+144)/40;
# U cost 1.2 + (228+0)/40; W cost 7.4 + (150+0)/40.
expected={'A':8.7,'B':9.925,'C':10.475,'D':14.475,'T':7.55,'U':6.9,'W':11.15}
for a,v in expected.items(): assert abs(result['remaining_losses'][a]-v)<1e-10,(a,result)
assert result['posterior']=={'A':.375,'B':.275,'C':0.,'D':.35}
assert result['action']=='U' and result['repair_after']=={'0':'A','1':'B'}
print(result)
print('Independent expected-loss and posterior checks passed.')

